<template><aside class="filter-panel"><div class="filter-header"><h5>Bộ lọc</h5><button v-if="hasFilters" class="clear-button" type="button" @click="reset">Xóa</button></div><div class="filter-section"><label>Danh mục</label><select v-model="categoryId" class="form-select form-select-sm" @change="changeCategory"><option value="">Tất cả danh mục</option><option v-for="c in categories" :key="c.id" :value="c.id">{{c.name}}</option></select></div><div class="filter-section"><div class="section-title">Khoảng giá</div><div class="range-grid"><input v-model.number="priceMin" class="form-control form-control-sm" type="number" min="0" placeholder="Từ" @change="emitFilters"/><input v-model.number="priceMax" class="form-control form-control-sm" type="number" min="0" placeholder="Đến" @change="emitFilters"/></div></div><div v-if="loading" class="filter-loading">Đang tải bộ lọc…</div><div v-for="f in dynamicFilters" v-else :key="f.definitionId" class="filter-section"><div class="section-title">{{f.name}}</div><div v-if="f.dataType==='NUMBER'" class="range-grid"><input v-model.number="selection(f.definitionId).min" class="form-control form-control-sm" type="number" placeholder="Từ" @change="emitFilters"/><input v-model.number="selection(f.definitionId).max" class="form-control form-control-sm" type="number" placeholder="Đến" @change="emitFilters"/></div><label v-for="o in (f.options||[])" v-else :key="o.id" class="option-row"><input v-model="selection(f.definitionId).values" type="checkbox" :value="o.id" @change="emitFilters"/> <span>{{o.value}}</span></label></div></aside></template>
<script setup lang="ts">import{computed,onMounted,reactive,ref}from'vue';import{getCategoryTree,getCategoryFilters}from'@/services/api/catalog/catalog.api';type Selection={values:string[];min?:number;max?:number};const emit=defineEmits<{filter:[value:{categoryId?:string;attributeFilters:Record<string,Selection>;giaTu?:number;giaDen?:number}]}>();const categories=ref<any[]>([]),categoryId=ref(''),dynamicFilters=ref<any[]>([]),selections=reactive<Record<string,Selection>>({}),priceMin=ref<number>(),priceMax=ref<number>(),loading=ref(false);const active= computed(()=>Object.fromEntries(Object.entries(selections).filter(([,s])=>s.values.length||s.min!==undefined||s.max!==undefined)));const hasFilters=computed(()=>!!categoryId.value||priceMin.value!==undefined||priceMax.value!==undefined||Object.keys(active.value).length>0);const selection=(id:string)=>selections[id]||(selections[id]={values:[]});const emitFilters=()=>emit('filter',{categoryId:categoryId.value||undefined,attributeFilters:active.value,giaTu:priceMin.value,giaDen:priceMax.value});const changeCategory=async()=>{dynamicFilters.value=[];Object.keys(selections).forEach(k=>delete selections[k]);if(categoryId.value){loading.value=true;try{dynamicFilters.value=await getCategoryFilters(categoryId.value)}finally{loading.value=false}}emitFilters()};const reset=async()=>{categoryId.value='';priceMin.value=undefined;priceMax.value=undefined;await changeCategory()};onMounted(async()=>{const flatten=(nodes:any[]):any[]=>nodes.flatMap(n=>[n,...flatten(n.children||n.childCategories||[])]);categories.value=flatten(await getCategoryTree())})</script>
<style scoped>.filter-panel{width:100%;border:1px solid #e5e7eb;background:#fff}.filter-header{display:flex;justify-content:space-between;padding:10px 14px;border-bottom:1px solid #e5e7eb}.filter-header h5{margin:0}.clear-button{border:0;background:transparent;color:#dc2626}.filter-section{padding:14px;border-bottom:1px solid #e5e7eb}.filter-section label,.section-title{display:block;margin-bottom:8px;font-weight:700;font-size:13px}.range-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px}.option-row{display:flex;gap:8px;margin:7px 0;font-size:13px}.filter-loading{padding:14px;color:#64748b}</style>
